const items = $input.all();
const tickets = items[0]?.json?.tickets || [];
const now = new Date();
const slaHours = 24;

let open = 0, pending = 0, resolved = 0, total = tickets.length;
let slaBreaches = [];

tickets.forEach(ticket => {
  const status = (ticket.status || '').toLowerCase();
  if (status === 'open' || status === 'new') open++;
  else if (status === 'pending') pending++;
  else if (status === 'solved' || status === 'closed') resolved++;

  if (status === 'open' || status === 'new' || status === 'pending') {
    const created = new Date(ticket.created_at);
    const hoursSinceCreated = (now - created) / (1000 * 60 * 60);
    if (hoursSinceCreated > slaHours) {
      slaBreaches.push({
        id: ticket.id,
        subject: ticket.subject,
        hoursOpen: Math.round(hoursSinceCreated),
        priority: ticket.priority || 'normal'
      });
    }
  }
});

return [{
  json: {
    timestamp: now.toISOString(),
    totalTickets: total,
    openTickets: open,
    pendingTickets: pending,
    resolvedTickets: resolved,
    slaBreachCount: slaBreaches.length,
    slaBreaches: JSON.stringify(slaBreaches.slice(0, 10)),
    hasSLABreach: slaBreaches.length > 0
  }
}];

